contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // run drives c.go with an arbitrary amount and asserts the invariant
    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);

        // observe owner and c balance before the call
        address ownerBefore = c.owner(); if (__ESBMC_reverted()) return;
        uint256 balBefore = address(c).balance;

        bool reverted;
        // perform the state-changing call; it must be top-level
        c.go{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // observe owner and c balance after the call
        address ownerAfter = c.owner(); if (__ESBMC_reverted()) return;
        uint256 balAfter = address(c).balance;

        // General rule: either the call reverted, or owner unchanged and C's balance is zero
        assert(reverted || (ownerAfter == ownerBefore && balAfter == 0));
    }

    receive() external payable {}
}

